    private void txt_1KeyPressed(java.awt.event.KeyEvent evt) {//GEN-FIRST:event_txt_1KeyPressed
        // TODO add your handling code here:
        System.out.println(evt);
        if(evt.getKeyCode() == evt.VK_A){
            txt_2.setText("A letra A foi pressionada!");
        }
        if(evt.getKeyCode() == evt.VK_B){
            txt_2.setText("A letra B foi pressionada!");
        }
        if(evt.getKeyCode() == evt.VK_C){
            txt_2.setText("A letra C foi pressionada!");
        }
    }//GEN-LAST:event_txt_1KeyPressed

    private void jPanel1MouseClicked(java.awt.event.MouseEvent evt) {//GEN-FIRST:event_jPanel1MouseClicked
        // TODO add your handling code here:
        txt_3.setText("X : " + evt.getX() + 
                "Y : " + evt.getY() + 
                "Botão: " + evt.getButton());
    }//GEN-LAST:event_jPanel1MouseClicked

